// app/users/[id]/edit/page.tsx
// Edit User Page — styled to match Edit Area Page
"use client";

import type React from "react";
import { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import Link from "next/link";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

import {
  ArrowLeft,
  Save,
  UserCog,
  Loader2,
  KeyRound,
  Eye,
  EyeOff,
} from "lucide-react";

import {
  getUserById,
  updateUser,
  resetUserPassword,
  type User,
} from "@/lib/api/user";

import { useToast } from "@/hooks/use-toast";

export default function EditUserPage() {
  const params = useParams();
  const router = useRouter();
  const { toast } = useToast();

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState<User | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Normal user form
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    role: "USER",
    isActive: "Active",
  });

  const [validationErrors, setValidationErrors] = useState({
    name: "",
  });

  // Password reset state
  const [newPassword, setNewPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [isResettingPassword, setIsResettingPassword] = useState(false);

  useEffect(() => {
    if (params.id) {
      fetchUserDetails();
    }
  }, [params.id]);

  const fetchUserDetails = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await getUserById(params.id as string);

      if (response.success && response.user) {
        const userData = response.user;

        setUser(userData);

        setFormData({
          name: userData.name,
          email: userData.email,
          role: userData.role,
          isActive: userData.isActive ? "Active" : "Inactive",
        });
      } else {
        setError(response.error || "Failed to fetch user details");

        toast({
          title: "Error",
          description:
            response.error || "Failed to fetch user details",
          variant: "destructive",
        });
      }
    } catch {
      setError("Failed to fetch user details");

      toast({
        title: "Error",
        description: "Failed to fetch user details",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const validateForm = () => {
    const errors = {
      name: "",
    };

    let isValid = true;

    if (!formData.name.trim()) {
      errors.name = "Full name is required";
      isValid = false;
    } else if (formData.name.trim().length < 3) {
      errors.name = "Name must be at least 3 characters";
      isValid = false;
    }

    setValidationErrors(errors);

    return isValid;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      toast({
        title: "Validation Error",
        description: "Please check the form for errors",
        variant: "destructive",
      });

      return;
    }

    setIsSubmitting(true);

    try {
      const response = await updateUser(params.id as string, {
        name: formData.name,
        role: formData.role as "USER",
        isActive: formData.isActive === "Active",
      });

      if (response.success) {
        toast({
          title: "Success",
          description: "User updated successfully",
        });

        router.push(`/users/${params.id}`);
      } else {
        toast({
          title: "Error",
          description: response.error || "Failed to update user",
          variant: "destructive",
        });
      }
    } catch {
      toast({
        title: "Error",
        description: "Failed to update user",
        variant: "destructive",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  // ------------------------------------------
  // RESET PASSWORD
  // ------------------------------------------
  const handleResetPassword = async () => {
    const trimmedPassword = newPassword.trim();

    if (!trimmedPassword) {
      toast({
        title: "Validation Error",
        description: "Please enter a new password",
        variant: "destructive",
      });

      return;
    }

    if (trimmedPassword.length < 6) {
      toast({
        title: "Validation Error",
        description: "Password must be at least 6 characters",
        variant: "destructive",
      });

      return;
    }

    const confirmed = window.confirm(
      `Are you sure you want to reset the password for ${user?.name}?`
    );

    if (!confirmed) {
      return;
    }

    setIsResettingPassword(true);

    try {
      const response = await resetUserPassword(
        params.id as string,
        trimmedPassword
      );

      if (response.success) {
        toast({
          title: "Password Reset",
          description: "User password has been reset successfully",
        });

        // Clear password after successful reset
        setNewPassword("");
        setShowPassword(false);
      } else {
        toast({
          title: "Error",
          description:
            response.error || "Failed to reset user password",
          variant: "destructive",
        });
      }
    } catch {
      toast({
        title: "Error",
        description: "Failed to reset user password",
        variant: "destructive",
      });
    } finally {
      setIsResettingPassword(false);
    }
  };

  // Loading State
  if (loading) {
    return (
      <div className="flex flex-1 items-center justify-center p-4">
        <div className="text-center">
          <Loader2 className="mx-auto mb-4 h-12 w-12 animate-spin text-[#8B0000]" />

          <p className="text-lg font-medium text-gray-400">
            Loading user details...
          </p>
        </div>
      </div>
    );
  }

  // Error State or User Not Found
  if (error || !user) {
    return (
      <div className="flex flex-1 items-center justify-center p-4">
        <div className="text-center">
          <UserCog className="mx-auto mb-4 h-12 w-12 text-gray-600" />

          <h1 className="mb-2 text-xl font-bold text-white">
            User Not Found
          </h1>

          <p className="mb-4 text-gray-400">
            {error || "The requested user does not exist."}
          </p>

          <Link href="/users">
            <Button className="bg-[#8B0000] text-white hover:bg-[#6B0000]">
              Back to Users
            </Button>
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 lg:p-8">
      <div className="mx-auto max-w-2xl">

        {/* Back Button */}
        <Link
          href={`/users/${params.id}`}
          className="mb-6 inline-flex items-center gap-2 text-gray-400 hover:text-white"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to User Details
        </Link>

        {/* ------------------------------------------
            EDIT USER CARD
        ------------------------------------------ */}
        <Card className="border-[#333] bg-[#222]">
          <CardHeader>
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-[#8B0000]">
                <UserCog className="h-5 w-5 text-white" />
              </div>

              <div>
                <CardTitle className="text-xl text-white">
                  Edit User
                </CardTitle>

                <CardDescription className="text-gray-400">
                  Update user details, role, and status
                </CardDescription>
              </div>
            </div>
          </CardHeader>

          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">

              {/* Role + Status */}
              <div className="grid gap-6 sm:grid-cols-2">

                {/* Role */}
                <div className="space-y-2">
                  <Label htmlFor="role" className="text-gray-300">
                    Role
                  </Label>

                  <Select
                    value={formData.role}
                    onValueChange={(value) =>
                      setFormData({
                        ...formData,
                        role: value,
                      })
                    }
                  >
                    <SelectTrigger className="border-[#333] bg-[#1a1a1a] text-white focus:ring-[#8B0000]">
                      <SelectValue />
                    </SelectTrigger>

                    <SelectContent className="border-[#333] bg-[#222]">
                      <SelectItem
                        value="USER"
                        className="text-white focus:bg-[#333] focus:text-white"
                      >
                        User
                      </SelectItem>

                    
                    </SelectContent>
                  </Select>
                </div>

                {/* Status */}
                <div className="space-y-2">
                  <Label htmlFor="status" className="text-gray-300">
                    Status
                  </Label>

                  <Select
                    value={formData.isActive}
                    onValueChange={(value) =>
                      setFormData({
                        ...formData,
                        isActive: value,
                      })
                    }
                  >
                    <SelectTrigger className="border-[#333] bg-[#1a1a1a] text-white focus:ring-[#8B0000]">
                      <SelectValue />
                    </SelectTrigger>

                    <SelectContent className="border-[#333] bg-[#222]">
                      <SelectItem
                        value="Active"
                        className="text-white focus:bg-[#333] focus:text-white"
                      >
                        Active
                      </SelectItem>

                      <SelectItem
                        value="Inactive"
                        className="text-white focus:bg-[#333] focus:text-white"
                      >
                        Inactive
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              {/* Name */}
              <div className="space-y-2">
                <Label htmlFor="name" className="text-gray-300">
                  Full Name <span className="text-red-500">*</span>
                </Label>

                <Input
                  id="name"
                  placeholder="e.g., Priya Sharma"
                  value={formData.name}
                  onChange={(e) => {
                    setFormData({
                      ...formData,
                      name: e.target.value,
                    });

                    setValidationErrors({
                      ...validationErrors,
                      name: "",
                    });
                  }}
                  required
                  className="border-[#333] bg-[#1a1a1a] text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
                />

                {validationErrors.name && (
                  <p className="text-xs text-red-500">
                    {validationErrors.name}
                  </p>
                )}
              </div>

              {/* Email */}
              <div className="space-y-2">
                <Label htmlFor="email" className="text-gray-300">
                  Email Address
                </Label>

                <Input
                  id="email"
                  value={formData.email}
                  disabled
                  className="border-[#333] bg-[#1a1a1a] text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
                />

                <p className="text-xs text-gray-500">
                  Email cannot be changed
                </p>
              </div>

              {/* Save buttons */}
              <div className="flex flex-col-reverse gap-3 pt-4 sm:flex-row sm:justify-end">
                <Link href={`/users/${params.id}`}>
                  <Button
                    type="button"
                    variant="outline"
                    disabled={isSubmitting}
                    className="w-full border-[#333] bg-transparent text-white hover:bg-[#333] sm:w-auto"
                  >
                    Cancel
                  </Button>
                </Link>

                <Button
                  type="submit"
                  disabled={isSubmitting}
                  className="w-full gap-2 bg-[#8B0000] text-white hover:bg-[#6B0000] disabled:opacity-50 sm:w-auto"
                >
                  {isSubmitting ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin" />
                      Saving...
                    </>
                  ) : (
                    <>
                      <Save className="h-4 w-4" />
                      Save Changes
                    </>
                  )}
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>

        {/* ------------------------------------------
            PASSWORD CONTROL CARD
        ------------------------------------------ */}
        <Card className="mt-6 border-[#333] bg-[#222]">
          <CardHeader>
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-[#333]">
                <KeyRound className="h-5 w-5 text-white" />
              </div>

              <div>
                <CardTitle className="text-xl text-white">
                  Password Control
                </CardTitle>

                <CardDescription className="text-gray-400">
                  Reset the password for this user
                </CardDescription>
              </div>
            </div>
          </CardHeader>

          <CardContent>
            <div className="space-y-5">

              {/* Warning */}
              <div className="rounded-lg border border-[#4a3030] bg-[#2a1c1c] p-4">
                <p className="text-sm text-gray-300">
                  You are resetting the password for{" "}
                  <span className="font-medium text-white">
                    {user.name}
                  </span>
                  .
                </p>

                <p className="mt-1 text-xs text-gray-500">
                  The user's current password cannot be viewed.
                  Enter a new password to replace it.
                </p>
              </div>

              {/* Password Input */}
              <div className="space-y-2">
                <Label
                  htmlFor="newPassword"
                  className="text-gray-300"
                >
                  New Password
                </Label>

                <div className="relative">
                  <Input
                    id="newPassword"
                    type={showPassword ? "text" : "password"}
                    value={newPassword}
                    onChange={(e) =>
                      setNewPassword(e.target.value)
                    }
                    placeholder="Enter new password"
                    disabled={isResettingPassword}
                    className="border-[#333] bg-[#1a1a1a] pr-11 text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
                  />

                  <button
                    type="button"
                    onClick={() =>
                      setShowPassword(!showPassword)
                    }
                    disabled={isResettingPassword}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 transition-colors hover:text-white disabled:cursor-not-allowed disabled:opacity-50"
                    aria-label={
                      showPassword
                        ? "Hide password"
                        : "Show password"
                    }
                  >
                    {showPassword ? (
                      <EyeOff className="h-4 w-4" />
                    ) : (
                      <Eye className="h-4 w-4" />
                    )}
                  </button>
                </div>

                <p className="text-xs text-gray-500">
                  Password must be at least 6 characters.
                </p>
              </div>

              {/* Reset Button */}
              <div className="flex justify-end pt-2">
                <Button
                  type="button"
                  onClick={handleResetPassword}
                  disabled={
                    isResettingPassword || !newPassword.trim()
                  }
                  className="w-full gap-2 bg-[#8B0000] text-white hover:bg-[#6B0000] disabled:cursor-not-allowed disabled:opacity-50 sm:w-auto"
                >
                  {isResettingPassword ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin" />
                      Resetting...
                    </>
                  ) : (
                    <>
                      <KeyRound className="h-4 w-4" />
                      Reset Password
                    </>
                  )}
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>

      </div>
    </div>
  );
}